<script setup lang="ts">
import { computed, ref, useId, watch } from 'vue'
import { Check, ChevronDown, RotateCcw, SlidersHorizontal } from 'lucide-vue-next'
export interface ShopFilters { sort: string; minimum: number; maximum: number; colors: string[]; inStock: boolean; onSale: boolean }
const props = withDefaults(defineProps<{ priceLimit?: number; initialSection?: string; resultCount?: number; modelValue?: Partial<ShopFilters>; colors?: { name: string; color: string }[] }>(), { priceLimit: 2000, initialSection: 'price', resultCount: 128, modelValue: () => ({}), colors: () => [{ name: 'Black', color: '#191919' }, { name: 'White', color: '#fff' }, { name: 'Blue', color: '#7e9caf' }, { name: 'Green', color: '#829376' }, { name: 'Red', color: '#ba544b' }] })
const emit = defineEmits<{ 'update:modelValue': [filters: ShopFilters]; apply: [filters: ShopFilters] }>()
const id = useId()
const limit = computed(() => Math.max(1, Number(props.priceLimit) || 1))
const defaults = (): ShopFilters => ({ sort: 'Relevance', minimum: 0, maximum: limit.value, colors: [], inStock: false, onSale: false })
const filters = ref<ShopFilters>({ ...defaults(), ...props.modelValue })
const section = ref(props.initialSection)
const applied = ref(false)
function normalize() { filters.value.minimum = Math.max(0, Math.min(limit.value, Number(filters.value.minimum) || 0)); filters.value.maximum = Math.max(filters.value.minimum, Math.min(limit.value, Number(filters.value.maximum) || 0)) }
normalize()
watch(() => props.modelValue, value => { filters.value = { ...defaults(), ...value, colors: [...(value.colors ?? [])] }; normalize() }, { deep: true })
watch(() => props.priceLimit, normalize)
watch(() => props.initialSection, value => { section.value = value })
function update() { normalize(); applied.value = false; emit('update:modelValue', { ...filters.value, colors: [...filters.value.colors] }) }
function reset() { filters.value = defaults(); update() }
function apply() { update(); applied.value = true; emit('apply', { ...filters.value, colors: [...filters.value.colors] }) }
function toggleSection(name: string) { section.value = section.value === name ? '' : name }
</script>
<template>
  <form class="shop-filters" aria-label="Product filters" @submit.prevent="apply">
    <header><h3><SlidersHorizontal :size="18" aria-hidden="true" />Filters</h3><button type="button" aria-label="Reset filters" title="Reset filters" @click="reset"><RotateCcw :size="17" aria-hidden="true" /></button></header>
    <label class="sort-field"><span>Sort by</span><select v-model="filters.sort" aria-label="Sort products" @change="update"><option v-for="sort in ['Relevance','Price: low to high','Price: high to low','Top rated']" :key="sort">{{ sort }}</option></select></label>
    <div class="filter-section"><button type="button" class="section-toggle" :aria-expanded="section === 'price'" :aria-controls="`${id}-price`" @click="toggleSection('price')"><span>Price</span><small>${{ filters.minimum }} - ${{ filters.maximum }}</small><ChevronDown :size="16" aria-hidden="true" /></button><div v-if="section === 'price'" :id="`${id}-price`" class="price-content"><input v-model.number="filters.maximum" type="range" :min="filters.minimum" :max="limit" step="1" aria-label="Maximum price range" @input="update" /><div class="price-inputs"><label><span>$</span><input v-model.number="filters.minimum" type="number" min="0" :max="filters.maximum" aria-label="Minimum price" @change="update" /></label><span>to</span><label><span>$</span><input v-model.number="filters.maximum" type="number" :min="filters.minimum" :max="limit" aria-label="Maximum price" @change="update" /></label></div></div></div>
    <div class="filter-section"><button type="button" class="section-toggle" :aria-expanded="section === 'colors'" :aria-controls="`${id}-colors`" @click="toggleSection('colors')"><span>Color</span><small>{{ filters.colors.length || 'Any' }}</small><ChevronDown :size="16" aria-hidden="true" /></button><div v-if="section === 'colors'" :id="`${id}-colors`" class="color-options"><label v-for="color in colors" :key="color.name" :title="color.name"><input v-model="filters.colors" type="checkbox" :value="color.name" :aria-label="color.name" @change="update" /><span class="swatch" :style="{ background: color.color }"><Check v-if="filters.colors.includes(color.name)" :size="14" aria-hidden="true" /></span><span>{{ color.name }}</span></label></div></div>
    <div class="quick-filters"><label><span>In stock</span><input v-model="filters.inStock" type="checkbox" role="switch" @change="update" /></label><label><span>On sale</span><input v-model="filters.onSale" type="checkbox" role="switch" @change="update" /></label></div>
    <footer><button type="button" @click="reset">Reset</button><button type="submit"><Check v-if="applied" :size="15" aria-hidden="true" />{{ applied ? 'Applied' : `Show ${resultCount} results` }}</button></footer>
  </form>
</template>
<style scoped>
