label:focus-within{outline:2px solid #5433eb}.color-options{display:flex;flex-wrap:wrap;gap:13px;padding:5px 0 15px}.color-options label{position:relative;display:grid;justify-items:center;gap:5px;cursor:pointer;font-size:9px}.color-options input{position:absolute;opacity:0}.swatch{display:grid;width:27px;height:27px;place-items:center;border:1px solid #bbb;border-radius:50%}.swatch svg{color:#fff;background:#5433eb;border-radius:50%;padding:1px}.color-options input:checked+.swatch{outline:2px solid #5433eb;outline-offset:3px}.color-options input:focus-visible+.swatch{outline:2px solid #5433eb;outline-offset:3px}.quick-filters{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:15px 0;font-size:12px}.quick-filters label{display:flex;align-items:center;justify-content:space-between;gap:6px}.quick-filters input{appearance:none;width:29px;height:18px;flex-shrink:0;margin:0;border-radius:999px;background:#ccc;cursor:pointer;position:relative}.quick-filters input::after{content:'';position:absolute;top:3px;left:3px;width:12px;height:12px;border-radius:50%;background:#fff}.quick-filters input:checked{background:#5433eb}.quick-filters input:checked::after{left:14px}.shop-filters footer{display:flex;gap:10px;padding-top:7px}.shop-filters footer button{min-height:38px;border:0;border-radius:999px;background:transparent;font-size:12px}.shop-filters footer button:first-child{padding:0 10px;text-decoration:underline}.shop-filters footer button:last-child{display:flex;align-items:center;justify-content:center;gap:6px;flex:1;background:#5433eb;color:white;padding:8px 15px}.shop-filters :is(button,select,input):focus-visible{outline:2px solid #5433eb;outline-offset:2px}
</style>
